      "proposed_laureates": ["Immanuel Bloch", "Markus Greiner", "Peter Zoller"],
      "assessment": {
        "nobel_worthiness": "Optical-lattice quantum simulation made controlled many-body physics experimentally accessible and opened a major new regime for studying quantum matter.",
        "attribution": "Bloch and Greiner provided landmark experimental demonstrations; Zoller helped establish the theoretical vision. The broader development involved many groups.",
        "maturity": "The platform and its scientific impact have been demonstrated over many years across laboratories.",
        "uncertainties": ["The boundary between this achievement and the broader development of ultracold-gas physics is not sharp."]
      }
    },
